WITH m AS (SELECT loan_id, snapshot_date, CASE WHEN days_past_due=0 THEN 0 WHEN days_past_due<30 THEN 1 WHEN days_past_due<60 THEN 2 WHEN days_past_due<90 THEN 3 ELSE 4 END AS b, loan_status, LEAD(CASE WHEN days_past_due=0 THEN 0 WHEN days_past_due<30 THEN 1 WHEN days_past_due<60 THEN 2 WHEN days_past_due<90 THEN 3 ELSE 4 END) OVER (PARTITION BY loan_id ORDER BY snapshot_date) AS bn, LEAD(snapshot_date) OVER (PARTITION BY loan_id ORDER BY snapshot_date) AS dn FROM loan_monthly_snapshot) SELECT COUNT(*), ROUND(100.0*COUNT(*) FILTER (WHERE bn=0)/COUNT(*),1) FROM m WHERE snapshot_date=DATE '2025-01-31' AND dn=DATE '2025-02-28' AND loan_status<>'Closed' AND b=1
